import{_ as t,c as a,a6 as s,o as i}from"./chunks/framework.CsOMnFVz.js";const y=JSON.parse('{"title":"Redis Big Keys, Hot Keys, and Expired Keys","description":"","frontmatter":{},"headers":[],"relativePath":"en/redis/RedisKey.md","filePath":"en/redis/RedisKey.md"}'),o={name:"en/redis/RedisKey.md"};function n(r,e,l,h,d,c){return i(),a("div",null,e[0]||(e[0]=[s(`<h1 id="redis-big-keys-hot-keys-and-expired-keys" tabindex="-1">Redis Big Keys, Hot Keys, and Expired Keys <a class="header-anchor" href="#redis-big-keys-hot-keys-and-expired-keys" aria-label="Permalink to &quot;Redis Big Keys, Hot Keys, and Expired Keys&quot;">​</a></h1><h2 id="expired-key-deletion-mechanism" tabindex="-1">Expired <code>key</code> Deletion Mechanism <a class="header-anchor" href="#expired-key-deletion-mechanism" aria-label="Permalink to &quot;Expired \`key\` Deletion Mechanism&quot;">​</a></h2><p>Let&#39;s understand <code>redis</code>&#39;s mechanism for deleting expired <code>key</code>s.</p><ul><li>Lazy deletion: With lazy deletion, expired data is not deleted automatically when it reaches its expiry time. Instead, the deletion happens when the <code>key</code> value is next fetched — at that point a check is made to determine whether the <code>key</code> has expired, and only if it has expired is the deletion performed. In other words, the next time you execute <code>get name</code>, the function <code>expirelfNeeded()</code> runs; that function decides whether the <code>key</code> has expired. If it has, <code>nil</code> is returned and then the <code>key</code> is deleted from memory.</li><li>Periodic deletion: This is implemented by <code>redis</code>&#39;s scheduled-task function. The function runs at a certain frequency, and each time it runs it takes a certain number of random <code>key</code>s from the keyspace to check, deleting any expired keys it finds. Note: not every scheduled task checks all the <code>key</code>s — it randomly checks a fixed number of <code>key</code>s. This mechanism is intended to prevent blocking the <code>redis</code> main process for too long and causing business blocking, but the trade-off is that expired <code>key</code>s free up memory more slowly. The period of periodic deletion is governed by the <code>hz</code> parameter.</li></ul><h3 id="the-relationship-between-redis-scheduled-tasks-and-the-hz-parameter" tabindex="-1">The Relationship Between <code>redis</code> Scheduled Tasks and the <code>hz</code> Parameter <a class="header-anchor" href="#the-relationship-between-redis-scheduled-tasks-and-the-hz-parameter" aria-label="Permalink to &quot;The Relationship Between \`redis\` Scheduled Tasks and the \`hz\` Parameter&quot;">​</a></h3><p>In order to periodically check resource and service status and perform the corresponding operations according to a predefined policy, Redis calls an internal function to execute a variety of background tasks, for example:</p><ul><li>Compute LRU information and remove expired keys.</li><li>Close client connections that have timed out.</li><li>Defragment hash-type data.</li><li>Perform RDB or AOF persistence-related operations.</li><li>Update statistics.</li></ul><p>These periodic tasks are what keep the Redis service running normally, and their execution frequency is specified by the value of the <code>hz</code> parameter, which defaults to 10, i.e., 10 times per second.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 永久修改该参数的值，可以在其配置文件中指定如下参数：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> n</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # n表示的是一个1~100返回的数值</span></span></code></pre></div><p><strong>Typical application scenario</strong></p><p>Redis proactively removes expired keys by running periodic tasks, and the process works as follows:</p><ol><li>Randomly check 20 keys from the set of keys that have an expiration time set.</li><li>Delete all expired keys found during the check.</li><li>If more than 25% of the checked keys have expired, start a new round of the task.</li></ol><p>If there are many expired keys, or the number of them grows very quickly, while Redis&#39;s proactive cleanup frequency is low, the expired keys will occupy a large amount of memory space and may affect the performance of the Redis service. Appropriately increasing the value of the <code>hz</code> parameter to raise the cleanup frequency is a good way to solve this problem.</p><p><strong>Value range and configuration recommendations</strong></p><p><code>hz</code> can take values from 1 to 500. Increasing the value of the <code>hz</code> parameter raises the execution frequency of all periodic tasks, but it also increases the CPU usage of the Redis service. The default value of 10 is usually sufficient in general cases. If your business scenario has high requirements on the execution frequency of certain periodic tasks, you can try adjusting the value within 100. Increasing <code>hz</code> to above 100 has a relatively large impact on CPU usage, so proceed with caution.</p><h2 id="big-keys-and-hot-keys" tabindex="-1">Big Keys and Hot Keys <a class="header-anchor" href="#big-keys-and-hot-keys" aria-label="Permalink to &quot;Big Keys and Hot Keys&quot;">​</a></h2><p>Big keys can be divided into two situations:</p><ul><li>The key&#39;s Value is large: for example, a String-type key reaching 10MB in size, or the total size of elements of a collection type (Hash, List, Set, etc.) reaching 100MB. Generally, a single String-type key that reaches 10kB, or a collection-type key whose total size reaches 50MB, is defined as a big key.</li><li>The key has many elements: for example, a Hash-type key whose number of elements reaches 10000. Generally, a collection-type key with more than 5000 elements is considered a big key.</li></ul><p>A hot key is usually judged by the frequency with which a key is operated and the resources it consumes, for example:</p><ul><li>A shard in a cluster instance processes 10000 requests per second, and 3000 of them operate on the same key.</li><li>The total bandwidth usage of one shard in a cluster instance (inbound bandwidth + outbound bandwidth) is 100Mbits/s, and 80Mbits of it is consumed by executing HGETALL on a Hash-type key.</li></ul><h3 id="what-impact-do-big-keys-hot-keys-have" tabindex="-1">What Impact Do Big Keys / Hot Keys Have? <a class="header-anchor" href="#what-impact-do-big-keys-hot-keys-have" aria-label="Permalink to &quot;What Impact Do Big Keys / Hot Keys Have?&quot;">​</a></h3><h4 id="big-keys" tabindex="-1">Big keys <a class="header-anchor" href="#big-keys" aria-label="Permalink to &quot;Big keys&quot;">​</a></h4><p><strong>Cause specification-change failures.</strong></p><p>During a Redis cluster specification change, data rebalancing is performed (migrating data between nodes). When a single key is too large, it triggers the Redis kernel&#39;s migration limit for a single key, causing data migration to time out and fail. The larger the key, the higher the probability of failure; keys larger than 512MB may trigger this problem.</p><p><strong>Cause data migration failures.</strong></p><p>During data migration, if a big key has too many elements, it will block the migration of the keys that follow it. The data of the subsequent keys will be placed in the memory buffer of the migrating machine; if the blocking lasts too long, the migration will fail.</p><p><strong>Easily cause uneven sharding in the cluster.</strong></p><ul><li>Uneven memory usage across shards. For example, one shard uses a high amount of memory, or even fills up first, causing the keys of that shard to be evicted, while also wasting resources on other shards.</li><li>Uneven bandwidth usage across shards. For example, one shard is frequently rate-limited while the other shards are not.</li></ul><p><strong>The latency of client commands increases.</strong></p><p>Slow operations on big keys cause subsequent commands to be blocked, resulting in a series of slow queries.</p><p><strong>Cause instance rate-limiting.</strong></p><p>High-frequency reads of a big key can saturate the instance&#39;s outbound bandwidth, leading to rate-limiting, a large number of command timeouts or slow queries, and harm to the business.</p><p><strong>Cause master/replica switchover.</strong></p><p>Performing the dangerous DEL operation on a big key may block the master node for a long time, causing a master/replica switchover.</p><h4 id="hot-keys" tabindex="-1">Hot keys <a class="header-anchor" href="#hot-keys" aria-label="Permalink to &quot;Hot keys&quot;">​</a></h4><p><strong>Easily cause uneven sharding in the cluster.</strong></p><p>The shard where the hot key resides receives a large amount of business access while the other shards are under low pressure. This not only easily creates a performance bottleneck on a single shard, but also wastes the computing resources of the other shards.</p><p><strong>Cause CPU to spike.</strong></p><p>A large number of operations on a hot key can cause the CPU to spike. If this is reflected in a single shard of the cluster, you can clearly see that the CPU usage of the shard hosting the hot key is high. This affects other requests, producing slow queries and harming overall performance. In a sudden business-traffic spike scenario it can even cause a master/replica switchover.</p><p><strong>Easily cause cache breakdown.</strong></p><p>When the request pressure on a hot key is too great and exceeds what Redis can bear, cache breakdown is likely to occur — that is, a large number of requests are directed straight to the backend database, causing the database access volume to surge or even the database to go down, thereby affecting other businesses.</p><h3 id="what-usage-recommendations-are-there-to-reduce-big-keys-and-hot-keys" tabindex="-1">What Usage Recommendations Are There to Reduce Big Keys and Hot Keys? <a class="header-anchor" href="#what-usage-recommendations-are-there-to-reduce-big-keys-and-hot-keys" aria-label="Permalink to &quot;What Usage Recommendations Are There to Reduce Big Keys and Hot Keys?&quot;">​</a></h3><ul><li>Keep <strong>string-type keys within 10KB</strong>, and keep the number of elements in hash, list, set, and zset <strong>under 5000 as much as possible</strong>.</li><li>The key naming prefix should be a business abbreviation, and special characters (such as spaces, newlines, single/double quotes, and other escape characters) are forbidden.</li><li>Redis transactions are weak, so it is not recommended to use them excessively.</li><li>Short-lived connections have poor performance; a client with a connection pool is recommended.</li><li>If Redis is only used as a data cache and data loss is tolerable, it is recommended to disable persistence.</li></ul><h4 id="about-big-keys" tabindex="-1">About big keys <a class="header-anchor" href="#about-big-keys" aria-label="Permalink to &quot;About big keys&quot;">​</a></h4><p><strong>Split the big key.</strong></p><p>This can be divided into the following scenarios:</p><ul><li><strong>The object is a String-type big key:</strong> try splitting the object into several key-value pairs, and use MGET or a pipeline of multiple GETs to fetch the values, spreading out the pressure of a single operation. For a cluster, this spreads the operation pressure across multiple shards, reducing the impact on a single shard.</li><li><strong>The object is a collection-type big key and must be stored/retrieved as a whole:</strong> such a scenario is strictly forbidden in design, because it cannot be split. An effective approach is to remove the big key from Redis and store it separately on another storage medium.</li><li><strong>The object is a collection-type big key, and only some elements need to be operated on each time:</strong> split the elements of the collection type. Taking the Hash type as an example, the client can define a number N of split keys; each time, compute a hash value of the field for HGET and HSET operations and take the modulus N to determine which key the field falls on. This implementation is similar to how Redis Cluster computes slots.</li></ul><p><strong>Transfer the big key separately to another storage medium.</strong></p><p>For big keys that cannot be split, this approach is recommended: store the data that does not fit Redis&#39;s capabilities on another storage medium, such as <a href="https://www.huaweicloud.com/intl/zh-cn/product/sfs.html" target="_blank" rel="noreferrer">SFS</a> or another NoSQL database, and delete the big key from Redis.</p><p>Note: deleting a big key directly with DEL is forbidden — it may cause Redis to block or even trigger a master/replica switchover.</p><p><strong>Set expiration times reasonably and clean up expired data periodically.</strong></p><p>Set expiration times reasonably to avoid historical data piling up in Redis. Because of Redis&#39;s lazy deletion policy, expired data may not be cleaned up in a timely manner; check whether the cleanup of expired Redis keys is slow.</p><h4 id="about-hot-keys" tabindex="-1">About hot keys <a class="header-anchor" href="#about-hot-keys" aria-label="Permalink to &quot;About hot keys&quot;">​</a></h4><p><strong>Use read/write separation.</strong></p><p>If a hot key is mainly caused by heavy read traffic, you can enable read/write separation on the client to reduce the impact on the master node. You can also add more replicas to satisfy read demand. However, having too many replicas has its own side effects: DCS master/replica nodes use star-shaped replication, meaning all replica nodes synchronize directly with the master node. This ensures the replicas are independent of each other and that replication latency is low, but the drawback is that when there are many replicas, the CPU and network load on the master node will be high.</p><p><strong>Use client-side caching / local caching.</strong></p><p>This approach requires knowing in advance which keys are the business&#39;s hot keys. Design a two-level cache architecture of client/local cache plus remote Redis: hot data is fetched from the local cache first, and writes update both at the same time. This can absorb most of the read pressure on hot data. The drawback is that it requires modifying the client architecture and code, and the cost of the refactor is relatively high.</p><p><strong>Design circuit-breaking / degradation mechanisms.</strong></p><p>Hot keys very easily cause cache breakdown. During peak hours requests pass straight through to the backend database, leading to a business avalanche. Therefore, optimizing hot keys must include designing circuit-breaking/degradation mechanisms in the system, so that in a breakdown scenario you can rate-limit and degrade services to protect system availability.</p><h3 id="how-to-root-out-big-keys-and-hot-keys" tabindex="-1">How to Root Out Big Keys and Hot Keys <a class="header-anchor" href="#how-to-root-out-big-keys-and-hot-keys" aria-label="Permalink to &quot;How to Root Out Big Keys and Hot Keys&quot;">​</a></h3><p>Starting with <code>Redis4.0</code>, you can use the <code>bigkeys</code> and <code>hotkeys</code> parameters of <code>redis-cli</code> to find big keys and hot keys.</p><p>Related commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bigkeys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --memkeys</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hotkeys</span></span></code></pre></div><h2 id="memory-eviction-policy" tabindex="-1">Memory Eviction Policy <a class="header-anchor" href="#memory-eviction-policy" aria-label="Permalink to &quot;Memory Eviction Policy&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[root@cs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]# redis-cli config get maxmemory-policy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;maxmemory-policy&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;noeviction&quot;</span></span></code></pre></div><table><thead><tr><th style="text-align:left;">Policy</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>noeviction</code></td><td style="text-align:left;">No keys are evicted. When memory is full, further writes return an error, while reads are unaffected.</td></tr><tr><td style="text-align:left;"><code>allkeys-lru</code></td><td style="text-align:left;">Least recently used. When memory is full, evicts the least recently used keys (the keys that have not been accessed for the longest time). If there are no keys to delete, it falls back to the <code>noeviction</code> policy.</td></tr><tr><td style="text-align:left;"><code>volatile-lru</code></td><td style="text-align:left;">Similar to LRU, but when memory is full, it evicts the least recently used keys among the keys that have an expiration time set.</td></tr><tr><td style="text-align:left;"><code>allkeys-lfu</code></td><td style="text-align:left;">Least frequently used. When memory is full, evicts the keys that have been accessed the fewest times.</td></tr><tr><td style="text-align:left;"><code>volatile-lru</code></td><td style="text-align:left;">Similar to the above, but when memory is full, it evicts the least frequently accessed keys among the keys that have an expiration time set.</td></tr><tr><td style="text-align:left;"><code>allkeys-random</code></td><td style="text-align:left;">When memory is full, evicts keys from memory at random. It can be any key, whether frequently used or not.</td></tr><tr><td style="text-align:left;"><code>volatile-random</code></td><td style="text-align:left;">Similar, but when memory is full, it randomly evicts keys among the keys that have an expiration time set.</td></tr><tr><td style="text-align:left;"><code>volatile-ttl</code></td><td style="text-align:left;">Among the keys that have an expiration time set, evicts the keys that are about to expire.</td></tr></tbody></table>`,66)]))}const u=t(o,[["render",n]]);export{y as __pageData,u as default};
